import os, hashlib, errno
from django.utils.encoding import force_text, force_bytes
from storages.compat import FileSystemStorage

class HashPathStorage(FileSystemStorage):
    """Storage that uses a hash of the file name to determine the path."""

    def save(self, name, content, max_length=None):
        if name is None:
            name = content.name
        hash_name = hashlib.md5(force_bytes(name)).hexdigest()
        path = os.path.join(self.location, hash_name[:2], hash_name[2:])
        try:
            os.makedirs(os.path.dirname(path))
        except OSError as e:
            if e.errno!= errno.EEXIST:
                raise
        return super(HashPathStorage, self).save(name, content)
